	SELECT seq_member.NEXTVAL FROM dual

INSERT INTO member (
	member_no, member_id, password, name, nick_name, email, phone_number,
	zip_code, basic_address, detail_address, gender, birthday,
	bank_name, bank_code, account_holder_name
) VALUES (
	#{memberNo}, #{memberId}, #{password}, #{name}, #{nickName}, #{email}, #{phoneNumber},
	#{zipCode}, #{basicAddress}, #{detailAddress}, #{gender}, #{birthday},
	#{bankName}, #{bankCode}, #{accountHolderName}
)

mapper.select:
SELECT COUNT(*) FROM member
AND status = #{status}
AND (member_id LIKE '%' || #{keyword} || '%' OR name LIKE '%' || #{keyword} || '%')

SELECT *
FROM (
	SELECT m.*, ROWNUM AS rn
	FROM (
		SELECT member_no, member_id, name, nick_name, email,
		       phone_number, created_at, purchase_count, status
		FROM member


				AND status = #{status}


				AND (member_id LIKE '%' || #{keyword} || '%'
				     OR name    LIKE '%' || #{keyword} || '%')


		ORDER BY created_at DESC
	) m
	WHERE ROWNUM <= #{endRow}
)
WHERE rn >= #{startRow}

mapper.update:
UPDATE member
SET status = #{status}
WHERE member_no = #{memberNo}
